  "actions": {
    "CREATE": { "data": {} },
    "ADD_ITEM": { "data": {} },
    "REMOVE_ITEM": { "data": {} },
    "PLACE": { "data": {} },
    "SHIP": { "data": {} },
    "CANCEL": { "data": {} },
    "CHARGE_OK": { "data": {} },
    "CHARGE_FAILED": { "data": {} }
  },
  "dataDomain": {},
  "specialRules": [
    { "name": "draft-full", "note": "addItem is refused when the draft holds 3 items" },
    { "name": "empty-order", "note": "place is refused on a draft with no item" },
    { "name": "payment-in-progress", "note": "cancel is refused while the order is placed" }
  ],
  "noOpRule": "A refused command changes nothing: post == pre."
}

// Captures trace windows from the real host (src/host.impl.ts) for one order id,
// projected onto the contract's state keys. Usage: node spec/capture.mjs [outDir]
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import createHost from '../src/host.impl.ts';

const outDir = process.argv[2] ?? 'spec/traces';
const ID = 'o';
const ACTIONS = ['CREATE', 'ADD_ITEM', 'REMOVE_ITEM', 'PLACE', 'SHIP', 'CANCEL', 'CHARGE_OK', 'CHARGE_FAILED'];

async function project(h) {
  const v = await h.order(ID);
  const pending = (await h.pendingEffects()).filter((e) => e.from === ID).length;
  return v ? { ...v, pending } : { status: 'none', items: 0, charges: 0, refunds: 0, pending };
}

async function apply(h, action) {
  const command = { CREATE: 'create', ADD_ITEM: 'addItem', REMOVE_ITEM: 'removeItem', PLACE: 'place', SHIP: 'ship', CANCEL: 'cancel' }[action];
  if (command) return h[command](ID);
  const e = (await h.pendingEffects()).find((x) => x.from === ID);
  if (e) await h.completeEffect(e.id, action === 'CHARGE_OK' ? 'ok' : 'failed');
}

async function run(script) {
  const h = await createHost();
  const lines = [];
  for (const action of script) {
    const pre = await project(h);
    await apply(h, action);
    lines.push(JSON.stringify({ pre, action, data: {}, post: await project(h) }));
  }
  return lines.join('\n') + '\n';
}

// Deterministic pseudo-random walks plus the named scenarios.
let seed = 7;
const rand = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return (seed >>> 16) % n; };
const scenarios = {
  happy: ['CREATE', 'ADD_ITEM', 'ADD_ITEM', 'PLACE', 'CHARGE_OK', 'SHIP', 'CANCEL', 'SHIP'],
  failed: ['CREATE', 'ADD_ITEM', 'PLACE', 'CANCEL', 'CHARGE_FAILED', 'CHARGE_OK', 'CANCEL'],
  refund: ['CREATE', 'ADD_ITEM', 'ADD_ITEM', 'ADD_ITEM', 'ADD_ITEM', 'REMOVE_ITEM', 'PLACE', 'PLACE', 'CHARGE_OK', 'CANCEL', 'CANCEL', 'SHIP'],
  draftCancel: ['ADD_ITEM', 'CREATE', 'CREATE', 'REMOVE_ITEM', 'PLACE', 'CANCEL', 'ADD_ITEM'],
};
for (let i = 0; i < 20; i++) {
  const walk = ['CREATE'];
  for (let j = 0; j < 12; j++) walk.push(ACTIONS[rand(ACTIONS.length)]);
  scenarios[`walk${i}`] = walk;
}

rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
for (const [name, script] of Object.entries(scenarios)) writeFileSync(join(outDir, `${name}.ndjson`), await run(script));
console.log(`wrote ${Object.keys(scenarios).length} traces to ${outDir}`);

