import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const ALL = ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'];
const view =(status, items, charges = 0, refunds = 0) => ({ status, items, charges, refunds });

async function placed(h, id = 'o1', items = 2) {
  await h.create(id);
  for (let i = 0; i < items; i++) await h.addItem(id);
  assert.deepEqual(await h.place(id), { ok: true });
  const effects = (await h.pendingEffects()).filter((e) => e.from === id);
  assert.equal(effects.length, 1);
  return effects[0];
}

test('fresh system has no orders and no effects', async () => {
  const h = await createHost();
  assert.equal(await h.order('x'), null);
  assert.deepEqual(await h.pendingEffects(), []);
});

test('unknown ids are refused', async () => {
  const h = await createHost();
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel']) {
    const r = await h[c]('nope');
    assert.equal(r.ok, false);
    assert.equal(typeof r.reason, 'string');
  }
  assert.equal(await h.order('nope'), null);
});

test('create, duplicate create refused', async () => {
  const h = await createHost();
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.deepEqual(await h.order('a'), view('draft', 0));
  assert.equal((await h.create('a')).ok, false);
});

test('items between 0 and 3', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.removeItem('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('draft', 3));
  assert.equal((await h.removeItem('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('draft', 2));
});

test('empty draft cannot be placed', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.place('a')).ok, false);
  assert.deepEqual(await h.pendingEffects(), []);
});

test('place requests one charge with amount = items', async () => {
  const h = await createHost();
  const e = await placed(h, 'a', 3);
  assert.equal(e.kind, 'payment.charge');
  assert.deepEqual(e.data, { amount: 3 });
  assert.deepEqual(await h.order('a'), view('placed', 3, 1));
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'retryPayment']) assert.equal((await h[c]('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('placed', 3, 1));
});

test('cancel while placed -> cancelling; charge ok -> cancelled with one refund', async () => {
  const h = await createHost();
  const e = await placed(h);
  assert.deepEqual(await h.cancel('o1'), { ok: true });
  assert.deepEqual(await h.order('o1'), view('cancelling', 2, 1));
  assert.equal((await h.pendingEffects()).length, 1);
  for (const c of ALL) assert.equal((await h[c]('o1')).ok, false);
  assert.deepEqual(await h.order('o1'), view('cancelling', 2, 1));
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.order('o1'), view('cancelled', 2, 1, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ALL) assert.equal((await h[c]('o1')).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.order('o1'), view('cancelled', 2, 1, 1));
});

test('cancelling: charge failed -> cancelled, no refund', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.cancel('o1');
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o1'), view('cancelled', 2, 1, 0));
  assert.deepEqual(await h.pendingEffects(), []);
});

test('cancel during the retry charge', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.completeEffect(e.id, 'failed');
  await h.retryPayment('o1');
  assert.deepEqual(await h.cancel('o1'), { ok: true });
  const [e2] = await h.pendingEffects();
  await h.completeEffect(e2.id, 'failed');
  assert.deepEqual(await h.order('o1'), view('cancelled', 2, 2, 0));
});

test('charge ok -> paid -> shipped, then frozen', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('o1'), view('paid', 2, 1));
  assert.equal((await h.addItem('o1')).ok, false);
  assert.equal((await h.place('o1')).ok, false);
  assert.deepEqual(await h.ship('o1'), { ok: true });
  assert.deepEqual(await h.order('o1'), view('shipped', 2, 1));
  for (const c of ['addItem', 'removeItem', 'place', 'ship', 'cancel']) assert.equal((await h[c]('o1')).ok, false);
});

test('first charge failed -> declined; only retryPayment accepted', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o1'), view('declined', 2, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ALL.filter((c) => c !== 'retryPayment')) assert.equal((await h[c]('o1')).ok, false);
  assert.deepEqual(await h.order('o1'), view('declined', 2, 1));
});

test('retry: new charge, ok -> paid', async () => {
  const h = await createHost();
  const e = await placed(h, 'o1', 3);
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.retryPayment('o1'), { ok: true });
  assert.deepEqual(await h.order('o1'), view('placed', 3, 2));
  const effects = await h.pendingEffects();
  assert.equal(effects.length, 1);
  assert.notEqual(effects[0].id, e.id);
  assert.equal(effects[0].kind, 'payment.charge');
  assert.deepEqual(effects[0].data, { amount: 3 });
  for (const c of ALL.filter((c) => c !== 'cancel')) assert.equal((await h[c]('o1')).ok, false);
  await h.completeEffect(effects[0].id, 'ok');
  assert.deepEqual(await h.order('o1'), view('paid', 3, 2));
  assert.deepEqual(await h.cancel('o1'), { ok: true });
  assert.deepEqual(await h.order('o1'), view('cancelled', 3, 2, 1));
});

test('retry failed -> failed, frozen', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.completeEffect(e.id, 'failed');
  await h.retryPayment('o1');
  const [e2] = await h.pendingEffects();
  await h.completeEffect(e2.id, 'failed');
  assert.deepEqual(await h.order('o1'), view('failed', 2, 2));
  assert.deepEqual(await h.pendingEffects(), []);
  for (const c of ALL) assert.equal((await h[c]('o1')).ok, false);
  assert.deepEqual(await h.order('o1'), view('failed', 2, 2));
});

test('retryPayment refused unless declined', async () => {
  const h = await createHost();
  assert.equal((await h.retryPayment('x')).ok, false);
  await h.create('d');
  await h.addItem('d');
  assert.equal((await h.retryPayment('d')).ok, false);
  const e = await placed(h, 'p');
  assert.equal((await h.retryPayment('p')).ok, false);
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.retryPayment('p')).ok, false);
  assert.deepEqual(await h.order('p'), view('paid', 2, 1));
});

test('cancel draft: no refund; cancel paid: one refund', async () => {
  const h = await createHost();
  await h.create('d');
  assert.deepEqual(await h.cancel('d'), { ok: true });
  assert.deepEqual(await h.order('d'), view('cancelled', 0));
  const e = await placed(h, 'p');
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.cancel('p'), { ok: true });
  assert.deepEqual(await h.order('p'), view('cancelled', 2, 1, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.cancel('p')).ok, false);
  assert.equal((await h.ship('p')).ok, false);
  assert.deepEqual(await h.order('p'), view('cancelled', 2, 1, 1));
});

test('completing an effect twice changes nothing', async () => {
  const h = await createHost();
  const e = await placed(h);
  await h.completeEffect(e.id, 'ok');
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('o1'), view('paid', 2, 1));
});

test('orders are independent; systems are fresh', async () => {
  const h = await createHost();
  const ea = await placed(h, 'a', 1);
  const eb = await placed(h, 'b', 2);
  assert.notEqual(ea.id, eb.id);
  await h.completeEffect(eb.id, 'failed');
  assert.deepEqual(await h.order('a'), view('placed', 1, 1));
  assert.deepEqual(await h.order('b'), view('declined', 2, 1));
  const h2 = await createHost();
  assert.equal(await h2.order('a'), null);
  assert.deepEqual(await h2.pendingEffects(), []);
});

