26	      CREATE: intent(),
27	      ADD_ITEM: intent(),
28	      REMOVE_ITEM: intent(),
29	      PLACE: intent(),
30	      SHIP: intent(),
31	      CANCEL: intent(),
32	      CHARGE_OK: intent(),
33	      CHARGE_FAILED: intent(),
34	      RETRY_PAYMENT: intent(),
35	    },
36	    acceptors: {
37	      CREATE: (model) => (proposal, { reject, next, unchanged }) => {
38	        if (model.status !== 'none') return reject('order-exists');
39	        next.status = 'draft';
40	        unchanged('items', 'charges', 'refunds', 'pending');
41	      },
42	      ADD_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
43	        if (model.status !== 'draft') return reject('not-a-draft');
44	        if (model.items >= MAX_ITEMS) return reject('draft-full');
45	        next.items = model.items + 1;
46	        unchanged('status', 'charges', 'refunds', 'pending');
47	      },
48	      REMOVE_ITEM: (model) => (proposal, { reject, next, unchanged }) => {
49	        if (model.status !== 'draft') return reject('not-a-draft');
50	        if (model.items <= 0) return reject('draft-empty');
51	        next.items = model.items - 1;
52	        unchanged('status', 'charges', 'refunds', 'pending');
53	      },
54	      PLACE: (model) => (proposal, { reject, next, unchanged }) => {
55	        if (model.status !== 'draft') return reject('not-a-draft');
56	        if (model.items <= 0) return reject('empty-order');
57	        next.status = 'placed';
58	        next.charges = model.charges + 1;
59	        next.pending = model.pending + 1;
60	        unchanged('items', 'refunds');
61	      },
62	      SHIP: (model) => (proposal, { reject, next, unchanged }) => {
63	        if (model.status !== 'paid') return reject('not-paid');
64	        next.status = 'shipped';
65	        unchanged('items', 'charges', 'refunds', 'pending');
66	      },
67	      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
68	        if (model.status === 'draft') {
69	          next.status = 'cancelled';
70	          unchanged('items', 'charges', 'refunds', 'pending');
71	          return;
72	        }
73	        if (model.status === 'paid') {
74	          next.status = 'cancelled';
75	          next.refunds = model.refunds + 1;
76	          unchanged('items', 'charges', 'pending');
77	          return;
78	        }
79	        if (model.status === 'placed') {
80	          next.status = 'cancelling';
81	          unchanged('items', 'charges', 'refunds', 'pending');
82	          return;
83	        }
84	        return reject('not-cancellable');
85	      },
