8	const ID = 'o';
9	const ACTIONS = ['CREATE', 'ADD_ITEM', 'REMOVE_ITEM', 'PLACE', 'SHIP', 'CANCEL', 'CHARGE_OK', 'CHARGE_FAILED', 'RETRY_PAYMENT'];
10	
11	async function project(h) {
12	  const v = await h.order(ID);
13	  const pending = (await h.pendingEffects()).filter((e) => e.from === ID).length;
14	  return v ? { ...v, pending } : { status: 'none', items: 0, charges: 0, refunds: 0, pending };
15	}
16	
17	async function apply(h, action) {
18	  const command = { CREATE: 'create', ADD_ITEM: 'addItem', REMOVE_ITEM: 'removeItem', PLACE: 'place', SHIP: 'ship', CANCEL: 'cancel', RETRY_PAYMENT: 'retryPayment' }[action];
19	  if (command) return h[command](ID);
20	  const e = (await h.pendingEffects()).find((x) => x.from === ID);
21	  if (e) await h.completeEffect(e.id, action === 'CHARGE_OK' ? 'ok' : 'failed');
22	}
23	
24	async function run(script) {
25	  const h = await createHost();
26	  const lines = [];
27	  for (const action of script) {
28	    const pre = await project(h);
29	    await apply(h, action);
30	    lines.push(JSON.stringify({ pre, action, data: {}, post: await project(h) }));
31	  }
32	  return lines.join('\n') + '\n';
33	}
34	
