// Replays the captured traces against the spec (positive control), then against
// hand-seeded mutants of it (negative control: each must fail some window).
// Usage: node spec/replay.mjs   (after node spec/capture.mjs)
import { readFileSync, writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadWindows, replaySpecResults } from '../tools/polygraph/scripts/replay.mjs';

const SPEC = 'spec/order.spec.cjs';
const windows = loadWindows('spec/traces');

function score(path) {
  const r = replaySpecResults(path, windows);
  if (!r.ok) return { pass: 0, fail: windows.length, failures: [r.error] };
  const failures = [];
  r.results.forEach((x, i) => {
    if (x.status !== 'pass') failures.push(`${windows[i].scenario}#${windows[i].index} ${windows[i].action} ${x.status} ${x.error ?? ''}`);
  });
  return { pass: windows.length - failures.length, fail: failures.length, failures };
}

const ref = score(SPEC);
console.log(`reference: ${ref.pass}/${windows.length} windows pass`);
for (const f of ref.failures.slice(0, 10)) console.log('  ' + f);

const source = readFileSync(SPEC, 'utf-8');
const MUTANTS = {
  'four-items': ['const MAX_ITEMS = 3;', 'const MAX_ITEMS = 4;'],
  'no-refund': ['next.refunds = model.refunds + 1;', 'next.refunds = model.refunds;'],
  'place-empty': ["if (model.items <= 0) return reject('empty-order');", ''],
  'cancel-placed-at-once': ["if (model.status === 'draft') {", "if (model.status === 'draft' || model.status === 'placed') {"],
  'cancelling-refused': ["if (model.status === 'placed') {\n          next.status = 'cancelling';", "if (false) {\n          next.status = 'cancelling';"],
  'cancelling-ok-no-refund': ["          next.status = 'cancelled';\n          next.refunds = model.refunds + 1;\n          unchanged('items', 'charges');",
    "          next.status = 'cancelled';\n          unchanged('items', 'charges', 'refunds');"],
  'cancelling-failed-declines': ["next.status = model.status === 'cancelling' ? 'cancelled'", "next.status = model.status === 'cancelling' ? 'declined'"],
  'ship-unpaid': ["if (model.status !== 'paid') return reject('not-paid');", "if (model.status !== 'paid' && model.status !== 'placed') return reject('not-paid');"],
  'fail-never-declines': ["model.charges < MAX_CHARGES ? 'declined' : 'failed'", "'failed'"],
  'retry-unbounded': ["if (model.status !== 'declined') return reject('not-declined');\n        if (model.charges >= MAX_CHARGES) return reject('already-retried');",
    "if (model.status !== 'declined' && model.status !== 'failed') return reject('not-declined');"],
  // (an answer only ever finds a placed order, so mutating its status guard is equivalent; mutate the pending guard instead)
  'answer-twice': ["if (model.pending <= 0) return reject('no-pending-charge');\n        next.pending = model.pending - 1;",
    "if (model.pending <= 0 && model.status !== 'failed') return reject('no-pending-charge');\n        next.pending = Math.max(0, model.pending - 1);",
    "next.status = model.status === 'placed' ? 'paid'", "next.status = model.status === 'placed' || model.status === 'failed' ? 'paid'"],
};
const dir = mkdtempSync(join(tmpdir(), 'order-mutants-'));
let blind = 0;
// Each mutant is a list of [from, to] pairs, applied in order to the first occurrence.
for (const [name, pairs] of Object.entries(MUTANTS)) {
  let mutated = source;
  for (let i = 0; i < pairs.length; i += 2) {
    if (!mutated.includes(pairs[i])) throw new Error(`mutant ${name}: pattern not found`);
    mutated = mutated.replace(pairs[i], pairs[i + 1]);
  }
  const path = join(dir, `${name}.cjs`);
  writeFileSync(path, mutated);
  const m = score(path);
  if (m.fail === 0) blind++;
  console.log(`mutant ${name}: ${m.fail} windows flipped${m.fail === 0 ? '  <-- BLIND SPOT' : ''}`);
}
process.exitCode = ref.fail > 0 || blind > 0 ? 1 : 0;

